import { useDefaultProps } from '@mui/material/DefaultPropsProvider';
import { useFormControl, type FormControlProps } from '@mui/material/FormControl';
import FormControlLabel, { type FormControlLabelProps } from '@mui/material/FormControlLabel';
import type { FormHelperTextProps } from '@mui/material/FormHelperText';
import type { FormLabelProps } from '@mui/material/FormLabel';
import RadioGroup, { type RadioGroupProps } from '@mui/material/RadioGroup';
import { mergeSlotProps } from '@mui/material/utils';
import { composeRefs } from '@radix-ui/react-compose-refs';
import clsx from 'clsx';
import { mergeSx } from 'merge-sx';
import { forwardRef, useId, type ReactNode, type Ref } from 'react';

import { SvRadio, type SvRadioProps } from '../sv-radio/sv-radio';
import { FieldHelp, FieldLabel, FieldRoot } from './field-layout';

type OptionRadioProps = Omit<SvRadioProps, 'value' | 'name' | 'checked' | 'defaultChecked'>;
export interface SvRadioOption {
  value: string;
  label: ReactNode;
  disabled?: boolean;
  slotProps?: {
    radio?: OptionRadioProps;
    label?: Omit<FormControlLabelProps, 'control' | 'label' | 'value' | 'checked' | 'name'>;
  };
}
export type SvRadioGroupProps = Omit<RadioGroupProps, 'children'> & {
  label?: ReactNode;
  helperText?: ReactNode;
  error?: boolean | undefined;
  disabled?: boolean | undefined;
  required?: boolean | undefined;
  slotProps?: {
    formControl?: FormControlProps;
    label?: FormLabelProps;
    radio?: OptionRadioProps;
    helperText?: FormHelperTextProps;
  };
} & ({ options: readonly SvRadioOption[]; children?: never } | { options?: never; children?: ReactNode });

declare module '@mui/material/styles' {
  interface ComponentsPropsList {
    SvRadioGroup: SvRadioGroupProps;
  }
  interface Components {
    SvRadioGroup?: { defaultProps?: Partial<SvRadioGroupProps> | undefined } | undefined;
  }
}

function optionRadioProps(common: OptionRadioProps = {}, local: OptionRadioProps = {}): OptionRadioProps {
  const merged = mergeSlotProps(local, common);
  return {
    ...merged,
    ...(common.ref || local.ref ? { ref: composeRefs(common.ref, local.ref) } : {}),
    slots: { ...common.slots, ...local.slots },
    slotProps: {
      input: (ownerState) => {
        const defaults =
          typeof common.slotProps?.input === 'function' ? common.slotProps.input(ownerState) : common.slotProps?.input;
        const overrides =
          typeof local.slotProps?.input === 'function' ? local.slotProps.input(ownerState) : local.slotProps?.input;
        return {
          ...mergeSlotProps(overrides, defaults ?? {}),
          ...(defaults?.ref || overrides?.ref ? { ref: composeRefs(defaults?.ref, overrides?.ref) } : {}),
        };
      },
      root: (ownerState) => {
        const defaults =
          typeof common.slotProps?.root === 'function' ? common.slotProps.root(ownerState) : common.slotProps?.root;
        const overrides =
          typeof local.slotProps?.root === 'function' ? local.slotProps.root(ownerState) : local.slotProps?.root;
        const defaultRef = defaults && 'ref' in defaults ? (defaults.ref as Ref<unknown>) : undefined;
        const overrideRef = overrides && 'ref' in overrides ? (overrides.ref as Ref<unknown>) : undefined;
        return {
          ...mergeSlotProps(overrides, defaults ?? {}),
          ...(defaultRef || overrideRef ? { ref: composeRefs<unknown>(defaultRef, overrideRef) } : {}),
        };
      },
    },
  };
}

export const SvRadioGroup = forwardRef<HTMLDivElement, SvRadioGroupProps>(function SvRadioGroup(inProps, ref) {
  const muiDefaults = useDefaultProps<Partial<SvRadioGroupProps>>({
    props: {},
    name: 'MuiRadioGroup',
  });
  const svDefaults = useDefaultProps<Partial<SvRadioGroupProps>>({
    props: {},
    name: 'SvRadioGroup',
  });
  const svProps = useDefaultProps({ props: inProps, name: 'SvRadioGroup' });
  const resolved = useDefaultProps({ props: svProps, name: 'MuiRadioGroup' });
  const {
    options: _options,
    children: _children,
    label,
    helperText,
    error: errorProp,
    disabled: disabledProp,
    required: requiredProp,
    className,
    sx: _sx,
    slotProps = {},
    ...props
  } = resolved;
  const contentProps = [inProps, svDefaults, muiDefaults].find(
    (value) => value.children !== undefined || value.options !== undefined
  );
  const options = contentProps?.options;
  const parent = useFormControl();
  const fieldDefaults = useDefaultProps<FormControlProps>({
    props: slotProps.formControl ?? {},
    name: 'MuiFormControl',
  });
  const disabled = disabledProp ?? slotProps.formControl?.disabled ?? parent?.disabled ?? fieldDefaults.disabled;
  const error = errorProp ?? slotProps.formControl?.error ?? parent?.error ?? fieldDefaults.error;
  const required = requiredProp ?? slotProps.formControl?.required ?? parent?.required ?? fieldDefaults.required;
  const id = useId();
  const labelId = slotProps.label?.id ?? `${id}-label`;
  const helpId = slotProps.helperText?.id ?? `${id}-help`;
  const describedBy =
    [
      ...new Set(
        [...(props['aria-describedby']?.split(/\s+/) ?? []), ...(helperText != null ? [helpId] : [])].filter(Boolean)
      ),
    ].join(' ') || undefined;
  const group = (
    <RadioGroup
      {...props}
      ref={ref}
      className={clsx('SvRadioGroup-root', className)}
      sx={mergeSx(muiDefaults.sx, svDefaults.sx, inProps.sx)}
      aria-labelledby={
        props['aria-labelledby'] ?? (props['aria-label'] === undefined && label != null ? labelId : undefined)
      }
      aria-describedby={describedBy}
      aria-invalid={props['aria-invalid'] ?? (error || undefined)}
      aria-required={props['aria-required'] ?? (required || undefined)}
    >
      {options !== undefined
        ? options.map((option) => {
            const radio = optionRadioProps(slotProps.radio, option.slotProps?.radio);
            return (
              <FormControlLabel
                {...option.slotProps?.label}
                key={option.value}
                value={option.value}
                label={option.label}
                disabled={option.disabled ?? option.slotProps?.label?.disabled ?? radio.disabled}
                slotProps={{
                  ...option.slotProps?.label?.slotProps,
                  typography: mergeSlotProps(option.slotProps?.label?.slotProps?.typography, { sx: { fontSize: 14 } }),
                }}
                sx={mergeSx({ m: 0, gap: '4px' }, option.slotProps?.label?.sx)}
                control={
                  <SvRadio
                    {...radio}
                    value={option.value}
                    disabled={option.disabled ?? radio.disabled}
                    required={radio.required ?? option.slotProps?.label?.required ?? required}
                  />
                }
              />
            );
          })
        : contentProps?.children}
    </RadioGroup>
  );
  const framed =
    options !== undefined ||
    label != null ||
    helperText != null ||
    disabledProp !== undefined ||
    errorProp !== undefined ||
    requiredProp !== undefined ||
    slotProps.formControl !== undefined;
  if (!framed) return group;
  return (
    <FieldRoot
      {...slotProps.formControl}
      disabled={disabled}
      error={error}
      required={required}
      className={clsx('SvRadioGroup-formControl', slotProps.formControl?.className)}
    >
      {label != null && (
        <FieldLabel
          {...slotProps.label}
          id={labelId}
          className={clsx('SvRadioGroup-label', slotProps.label?.className)}
        >
          {label}
        </FieldLabel>
      )}
      {group}
      {helperText != null && (
        <FieldHelp
          {...slotProps.helperText}
          id={helpId}
          className={clsx('SvRadioGroup-helperText', slotProps.helperText?.className)}
        >
          {helperText}
        </FieldHelp>
      )}
    </FieldRoot>
  );
});
